export interface Credentials {
  user: string;
  pass: string;
}

export interface Session {
  id: string;
  userId: string;
  createdAt: number;
}

const sessions = new Map<string, Session>();

export function login(credentials: Credentials): Session {
  const session: Session = {
    id: "sess-" + Date.now().toString(36),
    userId: credentials.user,
    createdAt: Date.now(),
  };
  sessions.set(session.id, session);
  return session;
}

export function logout(sessionId: string): void {
  sessions.delete(sessionId);
}

export function sessionFor(sessionId: string): Session | undefined {
  return sessions.get(sessionId);
}

export function rotate(sessionId: string): Session | undefined {
  const current = sessions.get(sessionId);
  if (current === undefined) return undefined;
  const next: Session = { ...current, id: "sess-" + Date.now().toString(36), createdAt: Date.now() };
  sessions.delete(sessionId);
  sessions.set(next.id, next);
  return next;
}

export function touch(sessionId: string, now = Date.now()): void {
  const current = sessions.get(sessionId);
  if (current !== undefined) {
    current.createdAt = now;
  }
}
